import fs from "node:fs";
import path from "node:path";
import { compileFromFile } from "json-schema-to-typescript";

const schemaPaths = [
  path.resolve("schemas/event.schema.json"),
  path.resolve("schemas/edition.schema.json"),
];
const outputPath = path.resolve("schemas/types.ts");

const bannerComment = `/* eslint-disable */
/**
 * This file was automatically generated by json-schema-to-typescript.
 * DO NOT MODIFY IT BY HAND. Instead, modify the source JSONSchema file,
 * and run the build script to regenerate this file.
 */`;

const helpers = `
// ============================================================
// Corpus types (scripts/lib/corpus.js): the stored files plus the
// fields the layout derives (scripts/lib/layout.js)
// ============================================================

/** A Category of edition.json plus the path of its result TSV. */
export interface CorpusCategory extends Category {
  /** master/<event_id>/<YYYY-MM-DD>/<category_id>.tsv */
  result_tsv: string;
}

/** An Edition directory: its date, weather file and Categories. */
export interface CorpusEdition {
  /** YYYY-MM-DD, the directory name */
  date: string;
  /** master/<event_id>/<YYYY-MM-DD>/weather-data.json when that file exists, else null */
  weather_file: string | null;
  categories: CorpusCategory[];
}

/** An Event directory: event.json plus its id, image path and Editions. */
export interface CorpusEvent extends RaceEvent {
  /** the directory name */
  id: string;
  /** master/<event_id>/image.webp */
  image: string;
  /** sorted by date */
  editions: CorpusEdition[];
}

// ============================================================
// TSV Row Types (for parsing result.tsv files)
// ============================================================

/** Time string in H:MM:SS format (e.g., "1:23:45", "0:05:30") */
export type TimeString = string;

/**
 * Overall rank value - either a numeric position or a race status flag.
 * Numeric values may contain commas (e.g., "1,234").
 * Status flags: DNF, DNS, DSQ, DQ, DNE, TOV, OPEN, SKIP
 */
export type OverallRankValue = string;

/** Race status values that appear in overall_rank column */
export type RaceStatus =
  | "DNF" // Did Not Finish
  | "DNS" // Did Not Start
  | "DSQ" // Disqualified
  | "DQ" // Disqualified (variant)
  | "DNE" // Did Not Enter
  | "TOV" // Time Over (exceeded time limit)
  | "OPEN" // Open participation (non-competitive)
  | "SKIP"; // Skipped

/**
 * A parsed TSV result row, keyed by semantic role.
 * Applications should use meta_columns and segment columns
 * from the Category schema to map TSV headers to these fields.
 */
export interface ParsedResultRow {
  // Meta fields
  overall_rank?: OverallRankValue;
  bib?: string;
  name?: string;
  age?: number;
  gender?: string;
  residence?: string;
  total_time?: TimeString;
  gender_rank?: number[];
  age_category?: string;
  age_rank?: number;
  penalty?: string;
  status?: string;
  guide_name?: string;
  citizen_rank?: number;
  citizen_category?: string;

  // Segment data - keyed by segment index
  segments?: ParsedSegmentData[];
}

/** Parsed data for a single sport segment */
export interface ParsedSegmentData {
  /** Total lap time for this segment */
  lap?: TimeString;
  /** Intermediate checkpoint times */
  checkpoints?: TimeString[];
  /** Ranking within this segment */
  rank?: number;
  /** Transition time to next segment */
  transition?: TimeString;
  /** Cumulative time from race start */
  cumulative_time?: TimeString;
  /** Cumulative ranking */
  cumulative_rank?: number;
}
`;

async function main() {
  try {
    console.log("Compiling JSON Schema to TypeScript definitions...");
    const style = {
      singleQuote: false,
      semi: true,
      printWidth: 100,
      tabWidth: 2,
    };
    const parts = [];
    for (const [i, schemaPath] of schemaPaths.entries()) {
      parts.push(
        await compileFromFile(schemaPath, {
          bannerComment: i === 0 ? bannerComment : "",
          style,
        }),
      );
    }

    const finalTs = parts.join("\n") + helpers;
    fs.writeFileSync(outputPath, finalTs, "utf8");
    console.log("Successfully generated schemas/types.ts!");
  } catch (error) {
    console.error("Failed to build schemas/types.ts:", error);
    process.exit(1);
  }
}

main();
